 if(half){const rim=Array.from({length:n},(_,i)=>[r*Math.sin(i*2*Math.PI/n),0,r*Math.cos(i*2*Math.PI/n)]).reverse();faces.push({id:1,name:'Tapak bulatan',color:FACE_COLORS[1],outline:true,vertices:rim});}
