/** Physical millimetres, independent of the screen preview size. No fit-to-page. */
const npEscape=text=>String(text).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));
const npPointKey=p=>p.slice(0,2).map(x=>Math.round(x*1e6)).join(',');
