   labEl('pour-size-label').textContent=cone?'j \xB7 jejari kedua-dua tapak':'a \xB7 sisi kedua-dua tapak';for(const [id,value] of [['pour-size',v.size],['pour-height',v.height]]){labEl(id).value=String(value);labEl(id+'-value').textContent=value+' cm';}
