  for(const [id,ms,en] of [['learn-projection-label','Pelan & Dongakan','Plans & Elevations'],['learn-calculation-label','Semakan Pengiraan','Calculation Steps'],['note-draw-projections','Latih pelan & dongakan','Practise plans & elevations'],['note-check-steps','Semak langkah untuk ukuran ini','Check steps with these measurements'],['note-check-description','Bina penyelesaian sendiri menggunakan ukuran dan pilihan \u03C0 di atas.','Build your own solution with the measurements and \u03C0 choice above.']])el(id).textContent=english?en:ms;
